const toolCall =
  $json.body?.message?.toolCalls?.[0] ||
  $json.body?.message?.toolCallList?.[0] ||
  $json.toolCalls?.[0] ||
  $json.toolCallList?.[0];

if (!toolCall) {
  throw new Error("No tool call found");
}

const toolCallId = toolCall.id;
const toolName = toolCall.function?.name;

let args = toolCall.function?.arguments;

if (typeof args === "string") {
  args = JSON.parse(args);
}

if (!args) {
  throw new Error("No booking arguments found");
}

if (!args.appointment_start) {
  throw new Error("Missing appointment_start");
}

const start = new Date(args.appointment_start);

if (isNaN(start.getTime())) {
  throw new Error("Invalid appointment_start");
}

// Extract timezone offset from appointment_start
// Example: 2026-05-21T16:00:00+03:00
function getTimezoneOffsetFromIso(isoString) {
  const match = isoString.match(/([+-]\d{2}:\d{2}|Z)$/);

  if (!match) {
    throw new Error("appointment_start must include timezone, example: 2026-05-21T16:00:00+03:00");
  }

  return match[1];
}

// Convert offset string to minutes
// Example: +03:00 -> 180
function offsetToMinutes(offset) {
  if (offset === "Z") return 0;

  const sign = offset.startsWith("+") ? 1 : -1;
  const [hours, minutes] = offset.slice(1).split(":").map(Number);

  return sign * ((hours * 60) + minutes);
}

// Format date using the same timezone offset as appointment_start
function formatWithOffset(date, offset) {
  const offsetMinutes = offsetToMinutes(offset);
  const localTime = new Date(date.getTime() + offsetMinutes * 60 * 1000);

  const datePart = localTime.toISOString().slice(0, 19);

  if (offset === "Z") {
    return `${datePart}Z`;
  }

  return `${datePart}${offset}`;
}

const timezoneOffset = getTimezoneOffsetFromIso(args.appointment_start);

// Default appointment duration: 1 hour
const end = new Date(start.getTime() + 60 * 60 * 1000);

const appointmentStartFormatted = formatWithOffset(start, timezoneOffset);
const appointmentEndFormatted = formatWithOffset(end, timezoneOffset);

const eventTitle = `Pest Control - ${args.pest_issue} - ${args.customer_name}`;

const safetyNotes = args.safety_notes || "No safety notes provided";

const eventDescription = `
Customer: ${args.customer_name}
Phone: ${args.phone_number}
Email: ${args.email}

Service Address: ${args.service_address}, ${args.city}
Property Type: ${args.property_type || "Not provided"}

Pest Issue: ${args.pest_issue}
Urgency: ${args.urgency}
Notes: ${args.notes || "No notes provided"}
Safety Notes: ${safetyNotes}

Appointment: ${args.appointment_time_label}
`.trim();

return [
  {
    json: {
      toolCallId,
      toolName,

      customer_name: args.customer_name,
      phone_number: args.phone_number,
      email: args.email,
      service_address: args.service_address,
      city: args.city,
      pest_issue: args.pest_issue,
      urgency: args.urgency,
      notes: args.notes || "",
      safety_notes: args.safety_notes || "",
      property_type: args.property_type || "",
      appointment_start: appointmentStartFormatted,
      appointment_end: appointmentEndFormatted,
      appointment_time_label: args.appointment_time_label,

      calendar_event: {
        title: eventTitle,
        start: appointmentStartFormatted,
        end: appointmentEndFormatted,
        location: `${args.service_address}, ${args.city}`,
        description: eventDescription,
      },
    },
  },
];

const booking = $('Prepare booking data').item.json;

const confirmationMessage =
  `You’re all set. Your appointment is confirmed for ${booking.appointment_time_label}, and a confirmation email has been sent to ${booking.email}.`;

return [
  {
    json: {
      results: [
        {
          toolCallId: booking.toolCallId,
          result: confirmationMessage
        }
      ]
    }
  }
];
